const cluster = require('cluster');
const express = require('express');
const { requireTraderAuth } = require('../auth');
const { Portfolio } = require('../models');

const router = express.Router();

router.post('/api/trading/rebalance', requireTraderAuth, async (req, res) => {
  const { portfolioId, targetModelWeightings } = req.body;

  const portfolio = await Portfolio.findOne({
    where: { id: portfolioId, accountId: req.trader.accountId },
  });
  if (!portfolio) {
    return res.status(403).json({ error: 'Access denied: portfolio does not belong to your account' });
  }

  process.send({
    cmd: 'RECALCULATE_PORTFOLIO_ALLOCATIONS',
    portfolioId,
    weightings: targetModelWeightings,
  });

  res.status(202).json({ accepted: true, portfolioId, message: 'Rebalance task queued on cluster' });
});
